INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (0, 'h1', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'headline', '', '', 'Thursday''s AI and chip sell-off (Nasdaq 100 -5%, S&P -4%, BTC -5.5%, ETH -7.7%) pushed every market to or below its range low, and all four are in Uptrend weak. BTC and ES printed swing failures at the range low on Friday; ETH and NQ trade below theirs. A week for reclaim trades with Setup Only size, around Tuesday''s CPI. Update 13 Nov: BTC lost its 75,000 range low and trades at the 0.618 retracement of the summer rally (about 69,000); ETH is testing the bottom of its 1,951 to 1,986 zone.', '', '', '', '', '', '');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (1, 'x1', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'exit', 'BTC', 'BTC', 'Exit in force, 200 hold active', '', '', '', '', '', 'Below every EMA: EMA50 78,520, EMA200 76,340 (8 closes below). Any long is a counter-trend range trade. Shorts are held until two closes back above the EMA200.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (2, 'x2', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'exit', 'ETH', 'ETH', 'Exit in force, 200 hold active', '', '', '', '', '', 'Confirmed Bearish since 9 Oct, 3 closes below the EMA200 (2,313). Shorts are held until two closes back above it.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (3, 'x3', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'exit', 'SPX', 'ES (S&P)', 'Exit rule hit 6 Nov', '', '', '', '', '', 'Two cash closes below the EMA50 (7,650; about 7,680 on ES) and the weekly trend turned Below both (pay attention). Friday closed 0.3% back above the EMA200 (7,357; about 7,386 on ES): Monday''s close is the second.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (4, 'x4', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'exit', 'NDX', 'NQ (est.)', 'Exit in force, 200 hold active', '', '', '', '', '', '7 closes below the EMA50 and 2 below the EMA200 (28,130; about 28,240 on NQ): shorts are held until two closes back above it. Weekly Below both for 4 weeks.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (5, 'l9', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'long', 'BTC', 'BTC', 'Build 1/3: probe at 65,690', '4H sweep of 65,690 that closes back above (alerted), or a reaction from the zone 64,200 to 65,200 with two 4H closes back above 65,690', 'Below the sweep low, at the latest under 63,800', '73,949 (about 4R from 65,800), then 75,000 (about 4.6R)', 'Setup Only, small: about a quarter of the planned risk', '65689.7', 'The 0.786 retracement of the July to September rally (57,718 to 87,397) is 64,069, and the zone is the July to August range top BTC broke out of on 19 to 21 Aug. Today''s low 67,680 already traded through the 0.618 to 0.65 (69,055 to 68,105). A daily close below 64,000 opens 60,112.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (6, 'l1', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'long', 'BTC', 'BTC', 'Build 2/3: range reclaim', 'Two 4H closes back above 73,949, then above 75,000 (your trigger, alerted)', 'Move the step 1 stop to break-even; this add''s stop below the reclaim low', 'EMA200 76,340, then mid 81,000', 'Setup Only: about a quarter of the planned risk', '75000', 'BTC lost 75,000 on 10 Nov; winning it back turns the probe into a free trade.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (7, 'l10', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'long', 'BTC', 'BTC', 'Build 3/3: trend confirmed', 'Daily close above the EMA12, 21 and 50 (EMA50 about 78,520 now) with Bullish confirmed after 3 closes, and two daily closes above the EMA200 (76,340), which ends the 200 hold rule', 'Trend exit: two daily closes below the EMA50', 'Hold while above the EMA50; range high 87,300 and the yearly open', 'Normal (the tested trend entry): about half of the planned risk; Setup Only until the macro cycle is back to Uptrend intact', '78522', 'The only step with a tested edge (profit factor about 3). The EMA levels move every day; the alerts report the closes.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (8, 'l8', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'long', 'ETH', 'ETH', 'Build 1/3: probe at 1,951 to 1,986', '4H sweep of 1,986 or 1,951 that closes back above (alerted), or two 4H closes back above 2,006 after trading in the zone', 'Below the sweep low (13 Nov low 1,909, so about 1,895 if this sweep is the trigger)', '2,178 (about 3.4R from 1,960 with a stop at 1,895), monthly open 2,255 (about 4.5R)', 'Setup Only, small: about a quarter of the planned risk', '1985.88', 'Your retracement zone 1,951 to 1,986, where the 0.618 to 0.65 retracement of the June to September rally (1,510 to 2,807) sits at 2,006 to 1,964; 10 Nov''s low 2,006 tagged the 0.618. A daily close below 1,951 opens 1,749, then the 1,427 to 1,512 demand zone. 13 Nov: traded to 1,909 and is back at 1,951; the 12H plain Stochastic crossed bullish below 20 on the candle that closed at 01:00 (supportive, not a trigger).');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (9, 'l2', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'long', 'ETH', 'ETH', 'Build 2/3: monthly open reclaim', 'Two 1H closes above 2,255 (monthly open), your clean-range 1H exception', 'Move the step 1 stop to break-even; this add''s stop below the reclaim low', 'Range low 2,350, then mid 2,528 and the yearly open 3,000', 'Setup Only: about a quarter of the planned risk', '2255', 'Overhead before 2,350: EMA12 2,288, EMA200 2,313, EMA21 2,328. Your alerts check 4H closes, so the 1H trigger is yours to watch.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (10, 'l3', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'long', 'ETH', 'ETH', 'Build 3/3: trend confirmed', 'Daily close above the EMA12, 21 and 50 (EMA50 about 2,330 now) with Bullish confirmed after 3 closes, two daily closes above the EMA200 (2,302), and two 4H closes back above your 2,350 range low', 'Trend exit: two daily closes below the EMA50', 'Mid 2,528, then the yearly open 3,000', 'Normal (the tested trend entry): about half of the planned risk; Setup Only until the macro cycle is back to Uptrend intact', '2350', 'The only step with a tested edge (profit factor about 3). The EMA50, EMA200 and 2,350 sit close together, so one reclaim covers all three.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (11, 'l4', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'long', 'SPX', 'ES (S&P)', 'Range low swing failure', 'Friday swept 7,329 and closed back above (low 7,322, close 7,402). Enter only on a hold of 7,329 on a 4H close after a retest, or a fresh sweep and reclaim', 'Below 7,322 (Friday''s low)', 'EMA100 7,608 and mid 7,620 (about 2.4R from 7,400 with a stop at 7,310)', 'Setup Only (weekly Below both, Uptrend weak)', '7329.25', 'Two daily closes below 7,329 end this setup and bring 7,045 into play (-4.8%).');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (12, 'l5', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'long', 'SPX', 'ES (S&P)', 'Sweep of 7,045', 'Sweep of 7,045 that closes back above, only after a breakdown below 7,329', 'Below the sweep', 'Range low 7,329 (+4%)', 'Setup Only, counter-trend', '7045', 'Your next support below the range.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (13, 'l6', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'long', 'NDX', 'NQ (est.)', 'Range low reclaim', 'Two 4H closes back above 27,220 on your NQ1! chart', 'Below the reclaim low', 'EMA200 about 28,240 (+3.7%), then mid 29,000', 'Setup Only (below EMA200, 200 hold active)', '27220', 'NQ is estimated at 27,073 on Friday''s close, 0.5% below. The alerts cannot see NQ 4H candles (no NQ intraday data), so watch this one on your chart; daily closes back above 27,220 do alert.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (14, 'l7', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'long', 'NDX', 'NQ (est.)', 'Downside bounce levels', 'Sweep of 26,393 or 25,455 that closes back above', 'Below the sweep', 'Range low 27,220', 'Setup Only, counter-trend', '26393', '26,393 is 2.5% below Friday''s estimate; Thursday''s estimated low was 26,704.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (15, 's1', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'short', '', '', 'ES rejection at mid 7,620 (conditional)', '', '', '', '', '', 'Short a rally into 7,620 that is rejected (high above mid, daily close back below), stop above the high, target the range low 7,329. Mid, EMA100 (7,608) and EMA21 (7,654) stack there. Judgment: mid-range shorts after a failed high tested +0.3 to +1.4R, but on only 5 to 6 trades.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (16, 's2', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'short', '', '', 'No new shorts at the lows', '', '', '', '', '', 'Every market sits at or below its range low, so a stop above the range is far from the target. Retests of a broken range low tested -0.14R. Existing shorts stay on under the 200 hold rule.');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (17, 'r1', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'rule', '', '', 'No front-running. A touch of a level is not a trigger: wait for the close back above.', '', '', '', '', '', '');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (18, 'r2', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'rule', '', '', 'All longs are counter-trend: all four markets are in Uptrend weak. Your tested trend edge is weak in Range and Bearish regimes, so Setup Only size and fewer trades.', '', '', '', '', '', '');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (19, 'r3', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'rule', '', '', 'BTC, ETH, ES and NQ fell together on 5 Nov. Count open longs as one correlated bet and cap their combined risk.', '', '', '', '', '', '');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (20, 'r4', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'rule', '', '', 'No new entries in the hour around CPI (Tue 14:30) and PPI (Fri 14:30).', '', '', '', '', '', '');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (21, 'r5', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'rule', '', '', 'Build swing longs in three steps: probe at the level, add on the range reclaim, main size on the confirmed trend. Total risk within your 1 to 3% swing band, about a quarter, a quarter and half (my suggestion, not tested). If step 1 stops out, only the probe is lost; without trend confirmation full size is never reached.', '', '', '', '', '', '');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (22, 'e1', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'risk', '', '', 'Tue 10 Nov 14:30 Zurich: US CPI (Oct), forecast 0.3% m/m, core 0.2% m/m', '', '', '', '', '', '');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (23, 'e2', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'risk', '', '', 'Wed 11 Nov: Veterans Day, US bond market closed, stocks open', '', '', '', '', '', '');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (24, 'e3', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'risk', '', '', 'Thu 12 Nov 14:30: jobless claims. Fri 13 Nov 14:30: PPI (Oct)', '', '', '', '', '', '');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (25, 'e4', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'risk', '', '', 'Fed speakers every day (Waller Tue 10:00, then Logan, Bowman, Goolsbee, Daly, Williams)', '', '', '', '', '', '');
INSERT INTO weekly_plan (pos, id, week, week_start, week_end, written, section, asset, market, title, "trigger", stop, target, risk_class, level, note) VALUES (26, 'e5', 'Week 46', '2026-11-09', '2026-11-15', '2026-11-08', 'risk', '', '', 'Action item: write down your CPI risk stance before Monday''s open.', '', '', '', '', '', '');
